-- Meeting Rooms Needed (Medium)
INSERT INTO coding_problems (slug, title, description, difficulty, category, type, tags, starter_code, test_cases, examples, constraints, points, order_index, time_limit_ms, memory_limit_kb, input_format, output_format, editorial, judged)
VALUES ($q$meeting-rooms$q$, $q$Meeting Rooms Needed$q$, $q$You are given n meetings. Meeting i runs from time s[i] up to, but not including, time e[i]. Two meetings that overlap need different rooms. A meeting that ends at time t does not overlap one that starts at time t.

Find the smallest number of rooms that can host all meetings.$q$, $q$Medium$q$, $q$Greedy$q$, 'code', ARRAY[$q$greedy$q$, $q$sorting$q$, $q$heap$q$, $q$intervals$q$]::text[], $q${"python": "import sys\n\n\ndef main():\n    lines = sys.stdin.read().split('\\n')\n    # Input:\n    # Line 1: n.\n    # Next n lines: s and e for each meeting (s < e).\n    # TODO: solve, then print the answer\n\n\nmain()\n", "javascript": "const lines = require('fs').readFileSync(0, 'utf8').split('\\n');\n// Input:\n// Line 1: n.\n// Next n lines: s and e for each meeting (s < e).\n// TODO: solve, then console.log the answer\n", "java": "import java.io.*;\nimport java.util.*;\n\npublic class Main {\n    public static void main(String[] args) throws IOException {\n        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));\n        List<String> lines = new ArrayList<>();\n        for (String s; (s = in.readLine()) != null; ) lines.add(s);\n        // Input:\n        // Line 1: n.\n        // Next n lines: s and e for each meeting (s < e).\n        // TODO: solve, then System.out.println the answer\n    }\n}\n", "cpp": "#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    // Input:\n    // Line 1: n.\n    // Next n lines: s and e for each meeting (s < e).\n    // TODO: read with cin / getline, solve, print the answer\n    return 0;\n}\n", "c": "#include <stdio.h>\n\nint main(void) {\n    // Input:\n    // Line 1: n.\n    // Next n lines: s and e for each meeting (s < e).\n    /* TODO: read with scanf / fgets, solve, print the answer */\n    return 0;\n}\n"}$q$::jsonb, '[]'::jsonb, $q$[{"input": "3\n0 30\n5 10\n15 20", "output": "2", "explanation": "The first meeting overlaps both others, which do not overlap each other."}, {"input": "2\n0 5\n5 10", "output": "1", "explanation": "Touching meetings can share a room."}]$q$::jsonb, ARRAY[$q$1 ≤ n ≤ 10 000$q$, $q$0 ≤ s < e ≤ 10^9$q$]::text[], 25, 1012, 2000, 262144, $q$Line 1: n.
Next n lines: s and e for each meeting (s < e).$q$, $q$One integer, the minimum number of rooms.$q$, $q$Sort meetings by start time and keep a min-heap of end times of rooms in use. For each meeting, if the earliest-ending room has end ≤ start, reuse it (pop) before pushing the new end. The heap size at the end is the answer. A sweep over sorted start and end times also works. O(n log n).$q$, false)
ON CONFLICT (slug) DO NOTHING;

